public class InnerJobRunMonitoringConfigurationFactory(Action<Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration>
{

    internal InnerJobRunS3MonitoringConfigurationFactory S3MonitoringConfigurationFactory { get; set; }

    internal InnerJobRunManagedPersistenceMonitoringConfigurationFactory ManagedPersistenceMonitoringConfigurationFactory { get; set; }

    protected override Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration Create()
    {
        var monitoringConfigurationResult = CreateMonitoringConfiguration();
        factoryAction?.Invoke(monitoringConfigurationResult);

        return monitoringConfigurationResult;
    }

    private Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration CreateMonitoringConfiguration()
    {
        var monitoringConfigurationResult = new Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration();

        return monitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRServerless.JobRunTypes.MonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3MonitoringConfiguration ??= S3MonitoringConfigurationFactory?.Build();
        result.ManagedPersistenceMonitoringConfiguration ??= ManagedPersistenceMonitoringConfigurationFactory?.Build();
    }

} // End Of Class

